type Payloads = {
  MigrationNotFound: { name: string };
  SchemaDrift: { config: string; result: unknown };
  Rollback: { status: "success" | "failed" | "cancelled" | "released" };
};

export declare namespace Errors {
  export type Name = keyof Payloads;
  export type Payload<N extends Name> = Payloads[N];
  export type Of<N extends Name = Name> = Error & {
    readonly kind: N;
    readonly payload: Payloads[N];
  };
}

export function makeError<N extends Errors.Name>(
  kind: N,
  payload: Errors.Payload<N>,
): Errors.Of<N> {
  const error = new Error(kind) as Errors.Of<N>;
  Object.assign(error, { kind, payload });
  return error;
}

/** Throw a registry error. Registry errors leave this package only through here; the one other
 * `throw` (`swallowRollback`) rethrows a foreign error. */
export function raise<N extends Errors.Name>(kind: N, payload: Errors.Payload<N>): never {
  throw makeError(kind, payload);
}

/** Narrow an unknown error to one registry entry; callers rethrow on mismatch. */
export function isError<N extends Errors.Name>(value: unknown, kind: N): value is Errors.Of<N> {
  return value instanceof Error && (value as Partial<Errors.Of>).kind === kind;
}

import type { Resource, Scope } from "@tinker/core";
import { isError, raise } from "./errors.ts";

export { isError };
export type { Errors } from "./errors.ts";

export declare namespace QueryLogger {
  /** Drizzle's logger shape, declared structurally: one call per statement. */
  export type Handle = {
    logQuery(query: string, params: unknown[]): void;
  };
}

export declare namespace Transaction {
  /** A callback transaction commits when its callback resolves and rolls back when it rejects.
   * The callback parameter needs `any`: `never` rejects native databases whose methods take
   * their concrete transaction handle. `Handle<DB>` still infers that exact handle from `DB`.
   * This is the one `any` in the package. */
  export type Database = {
    transaction<T>(cb: (tx: any) => Promise<T>): Promise<T>;
  };
  export type Handle<DB extends Database> = Parameters<Parameters<DB["transaction"]>[0]>[0];
}

/** Borrow the native database and keep its transaction callback open until this resource ends.
 * A successful end commits; other outcomes roll back. Cleanup waits for the database's
 * commit or rollback, preserving begin failures and unexpected cleanup errors. */
export function openTransaction<DB extends Transaction.Database>(
  db: DB,
  ctx: Resource.Ctx,
): Promise<Transaction.Handle<DB>> {
  const started = readTransaction(db);
  ctx.defer((end) => settleTransaction(started, end));
  return started.handle;
}

/** The live pieces of one open transaction: `handle` resolves from inside the callback,
 * `done` resolves on commit and rejects with `Rollback` on rollback, and `settle` wakes the
 * parked callback with the owning layer's end. */
type OpenTransaction<DB extends Transaction.Database> = {
  readonly handle: Promise<Transaction.Handle<DB>>;
  readonly done: Promise<void>;
  readonly settle: (end: Scope.End) => void;
};

/** Start `db.transaction(cb)` and hand back the handle from
 * inside the callback. The callback parks on `outcome` until the owning layer settles:
 * `end.status === "success"` returns (commit); anything else raises `Rollback` inside the callback
 * (rollback). `done` rejects with that `Rollback` — the `defer` swallows it by design
 * ({@link settleTransaction}), so nobody outside ever sees it. After the handle resolves, a
 * begin failure is impossible — the callback already ran — so the rejection tracker is a no-op
 * by then, which is intended. */
function readTransaction<DB extends Transaction.Database>(db: DB): OpenTransaction<DB> {
  let resolveOutcome!: (end: Scope.End) => void;
  const outcome = new Promise<Scope.End>((resolve) => {
    resolveOutcome = resolve;
  });
  let resolveTx!: (tx: Transaction.Handle<DB>) => void;
  let rejectTx!: (cause: unknown) => void;
  const handle = new Promise<Transaction.Handle<DB>>((resolve, reject) => {
    resolveTx = resolve;
    rejectTx = reject;
  });
  const done = db.transaction(async (tx: Transaction.Handle<DB>) => {
    resolveTx(tx);
    const end = await outcome;
    if (end.status !== "success") raise("Rollback", { status: end.status });
  });
  ignoreRejection(done.then(noop, rejectTx));
  return { handle, done, settle: resolveOutcome };
}

/** Settle the parked callback with the layer's end, then await the transaction's own promise so
 * a graceful close resolves only after the commit (or rollback) completed. */
function settleTransaction<DB extends Transaction.Database>(
  started: OpenTransaction<DB>,
  end: Scope.End,
): Promise<void> {
  started.settle(end);
  return started.done.then(noop, swallowRollback);
}

const noop = (): void => undefined;

/** A Drizzle logger that writes one `db query` log line per statement (`{ sql }` only —
 * params are data, never logged), bound to the db resource's `ctx.log`. */
export function createQueryLogger(ctx: Resource.Ctx): QueryLogger.Handle {
  return {
    logQuery: (query) => {
      ctx.log("db query", { sql: query });
    },
  };
}

/** Swallow the transaction's own rejection after teardown: a commit resolves (nothing to do),
 * a rollback rejects with the `Rollback` the factory raised on purpose — the layer's real
 * outcome was already recorded, so this error must not escape into `teardownErrors`. */
function swallowRollback(error: unknown): void {
  if (!isError(error, "Rollback")) throw error;
}

/** Track a begin failure the factory could not deliver (the callback never ran, so the handle
 * has no value): attach the shared no-op so the rejection is never unhandled, while the handle
 * keeps its rejection for a later `resolve`. After the handle resolved this is a no-op. */
function ignoreRejection(promise: Promise<unknown>): void {
  promise.then(noop, noop);
}

import { execFile, type ExecFileException } from "node:child_process";
import { createRequire } from "node:module";
import { dirname, join, resolve } from "node:path";
import { promisify } from "node:util";
import { readMigrationFiles } from "drizzle-orm/migrator";
import { migrate } from "drizzle-orm/pg-core/async/session";
import { raise } from "./errors.ts";

export declare namespace Migrations {
  export type Database = Parameters<typeof migrate>[1];
  export type Options = {
    migrationsFolder: string;
    /** Record this folder after the caller has brought an old db to its schema. */
    baseline?: string;
  };
}

/** Borrows the db or transaction. The caller owns locking and any baseline upgrade.
 * Requires Drizzle 1.0; its migrator owns the journal and pending-file order. */
export async function migrateDatabase(
  db: Migrations.Database,
  options: Migrations.Options,
): Promise<void> {
  const files = readMigrationFiles(options);
  const selected =
    options.baseline !== undefined
      ? files.filter((file) => file.name === options.baseline).map((file) => ({ ...file, sql: [] }))
      : files;
  if (options.baseline !== undefined && selected.length === 0)
    raise("MigrationNotFound", { name: options.baseline });
  await migrate(selected, db, options);
}

/** Runs the app's pinned Kit in dry-run mode; no database or migration file is changed.
 * Paths in the config are relative to its folder, as when running Kit there.
 * Node's execFile promise adds UTF-8 stdout to each rejection; argument errors throw before it. */
export async function checkDrift(config: string): Promise<void> {
  const path = resolve(config);
  const cwd = dirname(path);
  const kit = join(dirname(createRequire(path).resolve("drizzle-kit")), "bin.cjs");
  const { stdout } = await promisify(execFile)(
    process.execPath,
    [kit, "generate", "--config", path, "--explain", "--output", "json"],
    { cwd },
  ).catch((error: ExecFileException & { stdout: string }) => {
    let result: unknown;
    try {
      result = JSON.parse(error.stdout);
    } catch {
      throw error;
    }
    raise("SchemaDrift", { config: path, result });
  });
  const result: unknown = JSON.parse(stdout);
  if (
    typeof result !== "object" ||
    result === null ||
    !("status" in result) ||
    result.status !== "no_changes"
  )
    raise("SchemaDrift", { config: path, result });
}

import { operation, resource, tag } from "@tinker/core";
import type { PGlite } from "@electric-sql/pglite";
import { createQueryLogger, openTransaction, type Transaction } from "./index.ts";

export declare namespace Database {
  export type Config = { kind: "open"; url?: string } | { kind: "borrow"; client: PGlite };
  export type Handle = Awaited<ReturnType<typeof database.factory>>;
}

export declare namespace Migrate {
  export type Config = {
    migrationsFolder: string;
    /** Upgrade old tables and record their baseline using this transaction only. */
    baseline?: (tx: Transaction.Handle<Database.Handle>) => Promise<void>;
  };
}

export const config = tag<Database.Config>({ label: "pglite.config" });

/** Each root and namespace owns one lazy database. Borrowed clients keep their outside owner. */
export const database = resource({
  label: "pglite.database",
  target: "namespace",
  depends: { config },
  factory: async ({ config }, ctx) => {
    const { drizzle } = await import("drizzle-orm/pglite");
    ctx.signal.throwIfAborted();
    if (config.kind === "borrow")
      return drizzle({ client: config.client, logger: createQueryLogger(ctx) });
    const { PGlite } = await import("@electric-sql/pglite");
    ctx.signal.throwIfAborted();
    const client = await PGlite.create(config.url);
    ctx.defer(() => client.close());
    ctx.signal.throwIfAborted();
    return drizzle({ client, logger: createQueryLogger(ctx) });
  },
});

/** One native transaction per session; the session waits for its commit or rollback. */
export const transaction = resource({
  label: "pglite.transaction",
  target: "session",
  depends: { database },
  factory: ({ database }, ctx) => openTransaction(database, ctx),
});

export const migrationConfig = tag<Migrate.Config>({ label: "pglite.migrationConfig" });

/** Shares Stack's Postgres advisory lock so every migration path on this database agrees. */
const migrationLock = { classId: 1937006964, objectId: 1 };

/** Owns the entire migration transaction, even when called at the root. The answer follows
 * commit or rollback; cancellation checked before commit rolls back every stage together. */
export const migrate = operation({
  label: "pglite.migrate",
  depends: { database, config: migrationConfig },
  run: async ({ database, config }, ctx) => {
    ctx.signal.throwIfAborted();
    const { sql } = await import("drizzle-orm");
    ctx.signal.throwIfAborted();
    const { migrateDatabase } = await import("./migrations.ts");
    ctx.signal.throwIfAborted();
    await database.transaction(async (tx) => {
      ctx.signal.throwIfAborted();
      await tx.execute(
        sql`select pg_advisory_xact_lock(${migrationLock.classId}, ${migrationLock.objectId})`,
      );
      ctx.signal.throwIfAborted();
      await config.baseline?.(tx);
      ctx.signal.throwIfAborted();
      await migrateDatabase(tx, { migrationsFolder: config.migrationsFolder });
      ctx.signal.throwIfAborted();
    });
  },
});
